WITH exploded AS (SELECT id, customer_id, created_at, coupon_codes, k, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) li AS k, attr_value) SELECT id, k, attr_value, ROW_NUMBER() OVER (PARTITION BY customer_id, k ORDER BY created_at DESC, id, k) AS event_seq, ROW_NUMBER() OVER (ORDER BY created_at, id, k) AS row_seq, ROW_NUMBER() OVER (PARTITION BY k ORDER BY created_at, id, k) AS event_seq_2, LAST_VALUE(k) IGNORE NULLS OVER (PARTITION BY k ORDER BY created_at, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_k FROM exploded;
